outline_text:
{
  "title": "Employee Handbook Overview",
  "theme": "default",
  "paginate": true,
  "slides": [
    {
      "title": "How to Use This Deck",
      "summary": "The eight handbook areas in order; each slide names the policy page in the handbook wiki."
    },
    {
      "title": "Working Hours and Remote Policy",
      "summary": "Core hours 10 to 16; two office days per week; fully remote four weeks per year anywhere in the EU."
    },
    {
      "title": "Vacation",
      "summary": "30 days per year, five may carry over; apply in the tool two weeks ahead; no approvals needed in December."
    },
    {
      "title": "Sick Days",
      "summary": "Report by 9 in the team channel; a doctor's note from day three; long-term cases go to HR and the insurer."
    },
    {
      "title": "Expenses",
      "summary": "Submit within 30 days through the portal; receipts mandatory above 20 euros; the card is preferred over cash."
    },
    {
      "title": "Equipment",
      "summary": "Choose your laptop at onboarding; phones for on-call roles; accessories ordered by your lead through IT stock."
    },
    {
      "title": "Security Rules",
      "summary": "Hardware two-factor for every account; lock your screen; report phishing with the report button, never forward it."
    },
    {
      "title": "Communication Norms",
      "summary": "Default to public channels; direct messages for personal topics; reply within one workday; no expectation after hours."
    },
    {
      "title": "On-Call",
      "summary": "One week rotations, two engineers; the rota is published a quarter ahead; the allowance is on the payslip."
    },
    {
      "title": "The Review Cycle",
      "summary": "Goals in January, a mid-year talk in July, and the yearly review in December; feedback is written in the tool."
    },
    {
      "title": "Where Policies Live",
      "summary": "The handbook wiki is the single source; the printed PDF is refreshed quarterly; changes announced in the company channel."
    },
    {
      "title": "Who to Ask",
      "summary": "HR for people policies, IT for equipment and access, your lead for everything else; the HR desk hours are Tuesdays."
    },
    {
      "title": "Checklist for Your First Month",
      "summary": "Laptop, accounts, two-factor, handbook sign-off, and the first one-on-one booked; all items tracked in the onboarding checklist."
    },
    {
      "title": "Questions",
      "summary": "Bring them to the monthly onboarding question session or the people team channel; the FAQ page is linked from the handbook."
    }
  ]
}
